import{_ as i,K as n,a as l,c as o,ac as a,b as d,q as r}from"./chunks/framework.BSuaGltH.js";const _=JSON.parse('{"title":"易经：八卦名称、性质与取象","description":"以《说卦》为主线解释八卦的自然物象、卦德、亲属和身体象征，说明先后天方位与取象的使用边界。","frontmatter":{"title":"易经：八卦名称、性质与取象","description":"以《说卦》为主线解释八卦的自然物象、卦德、亲属和身体象征，说明先后天方位与取象的使用边界。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"易经专题","summary":"以《说卦》为主线解释八卦的自然物象、卦德、亲属和身体象征，说明先后天方位与取象的使用边界。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"易经：阴阳、卦画与六爻结构","link":"/life/personal/yijing/symbols"},"next":{"text":"易经：一卦的阅读步骤与解释边界","link":"/life/personal/yijing/hexagram-reading"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"易经：阴阳、卦画与六爻结构","link":"/life/personal/yijing/symbols"},"next":{"text":"易经：一卦的阅读步骤与解释边界","link":"/life/personal/yijing/hexagram-reading"}},"headers":[],"relativePath":"life/personal/yijing/trigrams.md","filePath":"life/personal/yijing/trigrams.md"}'),h={name:"life/personal/yijing/trigrams.md"};function s(p,t,g,c,u,f){const e=n("ArticleImage");return l(),o("div",null,[t[0]||(t[0]=a('<h1 id="易经-八卦名称、性质与取象" tabindex="-1">易经：八卦名称、性质与取象 <a class="header-anchor" href="#易经-八卦名称、性质与取象" aria-label="Permalink to &quot;易经：八卦名称、性质与取象&quot;">​</a></h1><p>“乾为天”最容易记，但八卦不只是给八种自然物贴标签。《说卦》同时讲八卦的性质、自然现象、亲属关系、动物、身体及其他物象。把这些不同层次分开，才能理解古注为什么有时由“天”谈“健”，有时又借“父”或“马”说明行动。</p><p>本篇主要依据<a href="https://zh.wikisource.org/wiki/%E6%98%93%E5%82%B3/%E8%AA%AA%E5%8D%A6" target="_blank" rel="noopener noreferrer">《说卦》第二至十一章</a>整理。“卦德”在这里指卦的性质与功能，不是给一个符号评道德等级。</p><h2 id="一张基础对照表" tabindex="-1">一张基础对照表 <a class="header-anchor" href="#一张基础对照表" aria-label="Permalink to &quot;一张基础对照表&quot;">​</a></h2>',4)),d("p",null,[r(e,{src:"/life/yijing/trigrams.svg",alt:"八卦基础图"})]),t[1]||(t[1]=a('<table tabindex="0"><thead><tr><th>卦</th><th>读音</th><th>自然物象</th><th>《说卦》所概括的性质</th><th>入门解释</th></tr></thead><tbody><tr><td>乾 ☰</td><td>qián</td><td>天</td><td>健</td><td>健行、发动、持续的力量</td></tr><tr><td>坤 ☷</td><td>kūn</td><td>地</td><td>顺</td><td>顺承、容载、使事物得到安顿</td></tr><tr><td>震 ☳</td><td>zhèn</td><td>雷</td><td>动</td><td>震动、发起，使静止状态改变</td></tr><tr><td>巽 ☴</td><td>xùn</td><td>风、木</td><td>入</td><td>进入、渗透、逐渐影响</td></tr><tr><td>坎 ☵</td><td>kǎn</td><td>水</td><td>陷</td><td>陷入、险处，行进面临障碍</td></tr><tr><td>离 ☲</td><td>lí</td><td>火、日、电</td><td>丽</td><td>附丽、依附，并由此谈光明</td></tr><tr><td>艮 ☶</td><td>gèn</td><td>山</td><td>止</td><td>止住、界限，知道何时暂停</td></tr><tr><td>兑 ☱</td><td>duì</td><td>泽</td><td>说</td><td>“说”通悦，和悦、交流</td></tr></tbody></table><p>“离”在日常汉语常指离开，但这里《说卦》的“丽”是附着之意；“兑，说也”的“说”按悦理解。学习古文时，不能把现代最熟悉的词义直接代入。</p><h2 id="乾与坤-发动和承载" tabindex="-1">乾与坤：发动和承载 <a class="header-anchor" href="#乾与坤-发动和承载" aria-label="Permalink to &quot;乾与坤：发动和承载&quot;">​</a></h2><p>乾在《说卦》里可以为天、君、父、马等。这些联想常围绕刚健、运行和统摄展开。坤可以为地、母、牛、布、釜、大舆等，涉及承载、容受、顺成和众多。自然物、器物和社会角色被组织进同一套象征语言。</p><p>这并不意味着“主动的人都是乾，被动的人都是坤”。<a href="./hexagrams-01-08#gua-01">乾</a>有“潜龙勿用”，需要潜藏；<a href="./hexagrams-01-08#gua-02">坤</a>有“直方大”，也包含自身可贵的德性。用“乾永远进、坤永远退”概括，会把原文中的阶段和条件删掉。</p><h2 id="震与巽-突发的动与深入的入" tabindex="-1">震与巽：突发的动与深入的入 <a class="header-anchor" href="#震与巽-突发的动与深入的入" aria-label="Permalink to &quot;震与巽：突发的动与深入的入&quot;">​</a></h2><p>雷声带来突然的震动，风则通过接触和穿行影响事物，因此震常被用来讨论起动与惊惧，巽常被用来讨论进入、顺入和渐次影响。<a href="./hexagrams-49-56#gua-51">震卦</a>并不是只讲威猛，也讲遭遇震动时怎样保持秩序；<a href="./hexagrams-57-64#gua-57">巽卦</a>同样不是一句“顺从即可”。</p><p>《说卦》既说巽为风，也说巽为木。读到含巽的卦，不必争论“究竟只能是哪一种”。应先问该篇经文用了什么具体物象，注家选取某一象的理由是什么；不能把所有列项一次性塞进同一句爻辞。</p><h2 id="坎与离-险陷与附丽" tabindex="-1">坎与离：险陷与附丽 <a class="header-anchor" href="#坎与离-险陷与附丽" aria-label="Permalink to &quot;坎与离：险陷与附丽&quot;">​</a></h2><p>坎为水，也以“陷”解释它的性质；离为火，同时强调附丽。这两组关系不对称：水并非每次都代表智慧或财富，火也并非每次都代表成功。<a href="./hexagrams-25-32#gua-29">坎卦</a>面对重复的险处，<a href="./hexagrams-25-32#gua-30">离卦</a>则讨论附着与明的条件。</p><p>组合时尤其要留意上下关系。水火构成<a href="./hexagrams-57-64#gua-63">既济</a>，火水构成<a href="./hexagrams-57-64#gua-64">未济</a>。经传据此提出不同解释；不能只把“有水有火”当成同一卦义，也不能把图直接当作现代物理实验。</p><h2 id="艮与兑-界限与和悦" tabindex="-1">艮与兑：界限与和悦 <a class="header-anchor" href="#艮与兑-界限与和悦" aria-label="Permalink to &quot;艮与兑：界限与和悦&quot;">​</a></h2><p>艮的山象可引出止、界限、门阙等关联；兑的泽象可引出和悦、口舌及交流。艮并非终身不动，兑也不是无条件讨好。读<a href="./hexagrams-49-56#gua-52">艮</a>和<a href="./hexagrams-57-64#gua-58">兑</a>时，应检查行动在哪里停止、和悦有无诚信和原则。</p><p>《说卦》第三章把天地、山泽、雷风、水火成对说明。这种结构强调相互关系，后世据之阐释先天图式；原句与后世具体画法之间仍然需要注解这一步，详见<a href="./diagrams">图谱</a>。</p><h2 id="亲属、身体和动物-三套并列取象" tabindex="-1">亲属、身体和动物：三套并列取象 <a class="header-anchor" href="#亲属、身体和动物-三套并列取象" aria-label="Permalink to &quot;亲属、身体和动物：三套并列取象&quot;">​</a></h2><table tabindex="0"><thead><tr><th>卦</th><th>亲属象</th><th>身体象</th><th>动物象</th></tr></thead><tbody><tr><td>乾</td><td>父</td><td>首</td><td>马</td></tr><tr><td>坤</td><td>母</td><td>腹</td><td>牛</td></tr><tr><td>震</td><td>长男</td><td>足</td><td>龙</td></tr><tr><td>巽</td><td>长女</td><td>股</td><td>鸡</td></tr><tr><td>坎</td><td>中男</td><td>耳</td><td>豕（猪）</td></tr><tr><td>离</td><td>中女</td><td>目</td><td>雉</td></tr><tr><td>艮</td><td>少男</td><td>手</td><td>狗</td></tr><tr><td>兑</td><td>少女</td><td>口</td><td>羊</td></tr></tbody></table><p>依据分别是《说卦》第八、九、十章。正文还列有更多取象，不能把上表当作全书允许使用的全部象。</p><p>“长男、中男、少男”与震、坎、艮中的一阳所处下、中、上位置相联系；巽、离、兑则以一阴的位置形成另一组。这是一种结构化解释。它既不说明“一阳比二阴更有价值”，也不能由此判断现实家庭谁该拥有决定权。身体取象同样不是医学诊断规则。</p><h2 id="先天与后天方位" tabindex="-1">先天与后天方位 <a class="header-anchor" href="#先天与后天方位" aria-label="Permalink to &quot;先天与后天方位&quot;">​</a></h2>',19)),d("p",null,[r(e,{src:"/life/yijing/bagua-orders.svg",alt:"先天与后天八卦方位，南上北下"})]),t[2]||(t[2]=a('<table tabindex="0"><thead><tr><th>方位</th><th>先天图常见安排</th><th>后天图常见安排</th></tr></thead><tbody><tr><td>南</td><td>乾</td><td>离</td></tr><tr><td>东南</td><td>兑</td><td>巽</td></tr><tr><td>东</td><td>离</td><td>震</td></tr><tr><td>东北</td><td>震</td><td>艮</td></tr><tr><td>北</td><td>坤</td><td>坎</td></tr><tr><td>西北</td><td>艮</td><td>乾</td></tr><tr><td>西</td><td>坎</td><td>兑</td></tr><tr><td>西南</td><td>巽</td><td>坤</td></tr></tbody></table><p>本图采用南上北下、东左西右。先天图与后天图并非谁“更准确”的两张地图，它们在易学传统中服务于不同的说明方式。《说卦》第五章有“帝出乎震”等运行次序，并明确说震为东方、巽为东南、离为南方等；先天的整套排列则需要结合后世图学理解。<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%9C%AC%E7%BE%A9_(%E5%9B%9B%E5%BA%AB%E5%85%A8%E6%9B%B8%E6%9C%AC)/%E5%85%A8%E8%A6%BD" target="_blank" rel="noopener noreferrer">《周易本义》图目</a>列有伏羲、文王的次序图和方位图。传统命名不等于图版已被考古确证为这些人物亲绘。</p><h2 id="为什么不把八卦表当作无限词典" tabindex="-1">为什么不把八卦表当作无限词典 <a class="header-anchor" href="#为什么不把八卦表当作无限词典" aria-label="Permalink to &quot;为什么不把八卦表当作无限词典&quot;">​</a></h2><p>一个物象有多个可能解释，正因如此才需要约束。比较“看到马便判定一定是乾”与“本句谈健行，所以注家借马说明其义”：后者解释了为何取象，前者只是机械配对。</p><p>王弼<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E7%95%A5%E4%BE%8B/%E6%98%8E%E8%B1%A1" target="_blank" rel="noopener noreferrer">《周易略例·明象》</a>明确质疑“定马于乾”式的拘泥。他并非否认经文有象，而是反对只追符号、忘记所要说明的意思。不同易学流派对取象的重视程度不同，参看<a href="./commentaries">注家比较</a>。</p><p>比较稳妥的次序是：先看经文真实出现的物与动作，再查传文怎样解释，最后讨论某种象数方法有没有新增解释力。如果加上越来越多的象之后，任何结果都能被解释，那就必须说明该说法的限制。</p><h2 id="练习-从图形回到句子" tabindex="-1">练习：从图形回到句子 <a class="header-anchor" href="#练习-从图形回到句子" aria-label="Permalink to &quot;练习：从图形回到句子&quot;">​</a></h2><ol><li>一阴在上、两阳在下是哪一卦？答：兑，不能因为上面断开就叫巽。</li><li>为什么“离，丽也”不能直接译成“离，离开也”？答：此处是古义附丽，应由篇内释词确定。</li><li>如果一段爻辞写“马”，能否只凭一个字就断言上下卦中一定有乾？答：不能，古人也曾批评这种强行配象。</li><li>后天图的北方与先天图的北方是否同卦？答：不同，后天坎、先天坤；比较前必须确认图式与方位。</li></ol><p><a href="./overview">返回专题</a> · <a href="./hexagram-reading">继续阅读一卦的方法</a></p>',9))])}const b=i(h,[["render",s]]);export{_ as __pageData,b as default};
